import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';


export type ToastType = 'success' | 'error' | 'warning' | 'info';

export interface Toast {
    id: number;
    type: ToastType;
    message: string;
    duration: number;
}

/**
 * ToastService
 * Modern toast notification system to replace alert() calls
 */
@Injectable({
    providedIn: 'root'
})
export class ToastService {
    private toastsSubject = new BehaviorSubject<Toast[]>([]);
    public toasts$ = this.toastsSubject.asObservable();

    private nextId = 1;
    private readonly DEFAULT_DURATION = 3000; // 3 seconds

    constructor() { }

    /**
     * Show a success toast (green)
     */
    success(message: string, duration: number = this.DEFAULT_DURATION): void {
        this.show('success', message, duration);
    }

    /**
     * Show an error toast (red)
     */
    error(message: string, duration: number = this.DEFAULT_DURATION): void {
        this.show('error', message, duration);
    }

    /**
     * Show a warning toast (orange)
     */
    warning(message: string, duration: number = this.DEFAULT_DURATION): void {
        this.show('warning', message, duration);
    }

    /**
     * Show an info toast (blue)
     */
    info(message: string, duration: number = this.DEFAULT_DURATION): void {
        this.show('info', message, duration);
    }

    /**
     * Show a toast notification
     */
    private show(type: ToastType, message: string, duration: number): void {
        const toast: Toast = {
            id: this.nextId++,
            type,
            message,
            duration
        };

        const currentToasts = this.toastsSubject.value;
        this.toastsSubject.next([...currentToasts, toast]);

        // Auto-remove after duration
        setTimeout(() => {
            this.remove(toast.id);
        }, duration);
    }

    /**
     * Remove a toast by id
     */
    remove(id: number): void {
        const currentToasts = this.toastsSubject.value;
        this.toastsSubject.next(currentToasts.filter(t => t.id !== id));
    }

    /**
     * Clear all toasts
     */
    clear(): void {
        this.toastsSubject.next([]);
    }
}
